1	import moment from 'moment';
2	import React, { useState, useEffect } from 'react';
3	import { ChevronDown, ChevronUp, ChevronRight, Menu } from 'lucide-react';
4	import Tooltip from '@hochhuth-consulting/hhhh-shared-ui/HHHH-UI/tooltips/Tooltip';
5	
6	
7	interface ResultTypeFilterProps {
8	    onFilterChange: (filters: string[]) => void;
9	    allFileTypeRefiners?: { RefinementValue: string }[];
10	    setResultTypesAllDoc: any;
11	    resultTypeAllDoc: any;
12	    clearFilterToggle: any;
13	    sites: any;
14	    selectedSiteTitles: any;
15	    setSelectedSiteTitles: any;
16	    resultTypeQueryPrepare: any;
17	    resultType: any;
18	    ContextValue: any;
19	    activeSites: any;
20	    activeSitesSelectedItems: any;
21	    setActiveSitesSelectedItems: (filters: string[]) => void;
22	    useForOMTTool: any;
23	}
24	
25	const ResultTypeFilter: React.FC<ResultTypeFilterProps> = ({
26	    useForOMTTool, activeSitesSelectedItems, setActiveSitesSelectedItems, activeSites,
27	    onFilterChange, resultType, allFileTypeRefiners, setResultTypesAllDoc, resultTypeAllDoc,
28	    clearFilterToggle, sites, selectedSiteTitles, setSelectedSiteTitles,
29	    resultTypeQueryPrepare, ContextValue
30	}) => {
31	    const [documentSelectAll, setDocumentSelectAll] = useState(false);
32	    const [documentTypes, setDocumentTypes] = useState<{ [key: string]: boolean }>({});
33	    const [standaloneSelectAll, setStandaloneSelectAll] = useState(false);
34	    const [standaloneTypes, setStandaloneTypes] = useState({ Task: false, Project: false, Portfolio: false });
35	
36	    // Select All spans ALL listed sites (visible + non-visible). Compute true state:
37	    // checked = every task list selected, indeterminate = some but not all, unchecked = none.
38	    const totalTaskLists = Array.isArray(activeSites)
39	        ? activeSites.reduce((total: number, site: any) => total + (site.TaskLists?.length || 0), 0)
40	        : 0;
41	    const selectedTaskListCount = activeSitesSelectedItems?.length || 0;
42	    const allSelectedSites = totalTaskLists > 0 && selectedTaskListCount === totalTaskLists;
43	    const someSelectedSites = selectedTaskListCount > 0 && selectedTaskListCount < totalTaskLists;
44	    const selectAllSitesRef = React.useRef<HTMLInputElement>(null);
45	    useEffect(() => {
46	        if (selectAllSitesRef.current) {
47	            selectAllSitesRef.current.indeterminate = someSelectedSites;
48	        }
49	    }, [someSelectedSites]);
50	
51	    const handleDocumentSelectAll = (checked: boolean) => {
52	        setDocumentSelectAll(checked);
53	        const newDocumentTypes = Object.keys(documentTypes)?.reduce((acc, key) => {
54	            acc[key as keyof typeof documentTypes] = checked;
55	            return acc;
56	        }, {} as typeof documentTypes);
57	        setDocumentTypes(newDocumentTypes);
58	    };
59	
60	    const handleDocumentTypeChange = (type: keyof typeof documentTypes, checked: boolean) => {
61	        const newDocumentTypes = { ...documentTypes, [type]: checked };
62	        setDocumentTypes(newDocumentTypes);
63	        const allSelected = !Object.keys(newDocumentTypes).some(key => !newDocumentTypes[key as keyof typeof newDocumentTypes]);
64	        const noneSelected = Object.keys(newDocumentTypes).every(key => !newDocumentTypes[key as keyof typeof newDocumentTypes]);
65	        if (allSelected) setDocumentSelectAll(true);
66	        else if (noneSelected) setDocumentSelectAll(false);
67	    };
68	
69	    const handleStandaloneSelectAll = (checked: boolean) => {
70	        setStandaloneSelectAll(checked);
71	        let newDocumentTypes: any;
72	        if (ContextValue?.useForOnlyTasks === undefined || ContextValue?.useForOnlyTasks != true) {
73	            setDocumentSelectAll(checked);
74	            newDocumentTypes = Object.keys(documentTypes).reduce((acc, key) => {
75	                acc[key as keyof typeof documentTypes] = checked;
76	                return acc;
77	            }, {} as typeof documentTypes);
78	            setDocumentTypes(newDocumentTypes);
79	        }
80	        const newStandaloneTypes = Object.keys(standaloneTypes).reduce((acc, key) => {
81	            acc[key as keyof typeof standaloneTypes] = checked;
82	            return acc;
83	        }, {} as typeof standaloneTypes);
84	        setStandaloneTypes(newStandaloneTypes);
85	    };
86	
87	    const handleStandaloneTypeChange = (type: keyof typeof standaloneTypes, checked: boolean) => {
88	        const newStandaloneTypes = { ...standaloneTypes, [type]: checked };
89	        setStandaloneTypes(newStandaloneTypes);
90	        const allSelected = Object.keys(newStandaloneTypes).every(key => newStandaloneTypes[key as keyof typeof newStandaloneTypes]);
91	        const noneSelected = Object.keys(newStandaloneTypes).every(key => !newStandaloneTypes[key as keyof typeof newStandaloneTypes]);
92	        if (allSelected) setStandaloneSelectAll(true);
93	        else if (noneSelected) setStandaloneSelectAll(false);
94	    };
95	
96	    useEffect(() => {
97	        const selectedFilters: string[] = [];
98	        if (ContextValue?.useForOnlyTasks === undefined || ContextValue?.useForOnlyTasks != true) {
99	            if (documentSelectAll) selectedFilters.push('Document');
100	            Object.keys(documentTypes)?.forEach(key => { if (documentTypes[key as keyof typeof documentTypes]) selectedFilters.push(key); });
101	        }
102	        Object.keys(standaloneTypes)?.forEach(key => { if (standaloneTypes[key as keyof typeof standaloneTypes]) selectedFilters.push(key); });
103	        let documentFileType = selectedFilters?.filter((e: any) => e !== 'Task' && e !== 'Portfolio' && e !== 'Project');
104	        if (documentFileType?.length > 0) setResultTypesAllDoc(false);
105	        onFilterChange(selectedFilters);
106	        resultType.current = selectedFilters;
107	    }, [documentTypes, standaloneTypes, onFilterChange, setResultTypesAllDoc]);
108	
109	    useEffect(() => {
110	        if (allFileTypeRefiners && allFileTypeRefiners?.length > 0) {
111	            setDocumentSelectAll(false);
112	            const initialState: { [key: string]: boolean } = {};
113	            allFileTypeRefiners?.forEach((item: any) => {
114	                if (resultTypeQueryPrepare?.length > 0 && resultTypeQueryPrepare?.includes(item.RefinementValue)) {
115	                    resultTypeQueryPrepare?.forEach((type: any) => {
116	                        if (item.RefinementValue.toLowerCase() === type.toLowerCase()) initialState[item.RefinementValue] = true;
117	                        else initialState[item.RefinementValue] = false;
118	                    });
119	                } else {
120	                    initialState[item.RefinementValue] = false;
121	                }
122	            });
123	            setDocumentTypes(initialState);
124	        } else {
125	            setDocumentSelectAll(false);
126	            setDocumentTypes({});
127	        }
128	    }, [allFileTypeRefiners]);
129	
130	    useEffect(() => {
131	        if (clearFilterToggle) {
132	            setDocumentSelectAll(false);
133	            const initialState: { [key: string]: boolean } = {};
134	            allFileTypeRefiners?.forEach((item: any) => { initialState[item.RefinementValue] = false; });
135	            setDocumentTypes(initialState);
136	            setStandaloneSelectAll(false);
137	            setStandaloneTypes({ Task: false, Project: false, Portfolio: false });
138	            setResultTypesAllDoc(false);
139	            onFilterChange([]);
140	            resultType.current = [];
141	            setSelectedSiteTitles([]);
142	        }
143	    }, [clearFilterToggle]);
144	
145	    const handleTaskListSelect = (siteData: any, taskList: any) => {
146	        const itemToAdd = {
147	            siteTitle: siteData.Site.Title,
148	            siteUrl: siteData.Site.Url,
149	            siteId: siteData.Site.SiteId,
150	            webId: siteData.Site.WebId,
151	            taskListTitle: taskList.Title,
152	            taskListId: taskList.Id,
153	            taskListUrl: taskList.Url,
154	            coverImage: taskList.Item_x005F_x0020_Cover
155	        };
156	        const existsIndex = activeSitesSelectedItems?.findIndex((item: any) => item.taskListId === taskList.Id);
157	        let newSelectedItems: any[] = [];
158	        if (existsIndex >= 0) {
159	            newSelectedItems = activeSitesSelectedItems?.filter((_: any, index: any) => index !== existsIndex);
160	        } else {
161	            newSelectedItems = [...activeSitesSelectedItems, itemToAdd];
162	        }
163	        setActiveSitesSelectedItems(newSelectedItems);
164	        const siteUrl = siteData?.Site?.Url;
165	        const siteTaskLists = siteData?.TaskLists || [];
166	        const allListsOfSiteSelected = siteTaskLists.length > 0 && siteTaskLists.every((tl: any) => newSelectedItems.some((item: any) => item.taskListId === tl.Id));
167	        if (allListsOfSiteSelected) {
168	            if (!selectedSiteTitles?.includes(siteUrl)) setSelectedSiteTitles([...selectedSiteTitles, siteUrl]);
169	        } else {
170	            if (selectedSiteTitles?.includes(siteUrl)) setSelectedSiteTitles(selectedSiteTitles.filter((t: any) => t !== siteUrl));
171	        }
172	    };
173	
174	    const getCoverImageUrl = (taskList: any): string | null => {
175	        if (!taskList) return null;
176	        const cover = taskList?.Item_x005F_x0020_Cover || taskList?.Item_x0020_Cover || taskList?.coverImage || taskList?.ItemCoverURL;
177	        if (!cover) return null;
178	
179	        let rawUrl: string | null = null;
180	        if (typeof cover === 'object') {
181	            rawUrl = cover?.Url || cover?.url || cover?.URI || null;
182	        } else if (typeof cover === 'string') {
183	            const trimmed = cover.trim();
184	            if (trimmed.startsWith('{')) {
185	                try {
186	                    const parsed = JSON.parse(trimmed);
187	                    rawUrl = parsed?.Url || parsed?.url || null;
188	                } catch (e) {
189	                    rawUrl = null;
190	                }
191	            } else {
192	                rawUrl = trimmed;
193	            }
194	        }
195	
196	        if (!rawUrl) return null;
197	
198	        if (rawUrl.startsWith('https://') || rawUrl.startsWith('http://')) {
199	            return rawUrl;
200	        }
201	        if (rawUrl.startsWith('//')) {
202	            return `https:${rawUrl}`;
203	        }
204	        if (rawUrl.startsWith('/')) {
205	            const origin = ContextValue?.siteUrl ? new URL(ContextValue.siteUrl).origin : (typeof window !== 'undefined' ? window.location.origin : 'https://hhhhteams.sharepoint.com');
206	            return `${origin}${rawUrl}`;
207	        }
208	        return `https://${rawUrl}`;
209	    };
210	
211	    const isTaskListSelected = (taskListId: any) => activeSitesSelectedItems?.some((item: any) => item.taskListId === taskListId);
212	
213	    const getInitials = (title: any) => title.split(' ').map((word: any) => word[0]).join('').substring(0, 2).toUpperCase();
214	
215	    const getRandomColor = (id: any) => {
216	        const colors = ['#6f42c1', '#dc3545', '#fd7e14', '#ffc107', '#28a745', '#20c997', '#17a2b8', '#007bff', '#e83e8c', '#6c757d'];
217	        const index = (id || '').split('').reduce((acc: any, char: any) => acc + char.charCodeAt(0), 0) % colors.length;
218	        return colors[index];
219	    };
220	
221	    const handleSelectAllSites = (e: any) => {
222	        if (e.target.checked) {
223	            const allTaskLists = activeSites.flatMap((siteData: any) =>
224	                (siteData?.TaskLists || []).map((taskList: any) => ({
225	                    siteTitle: siteData.Site.Title, siteUrl: siteData.Site.Url, siteId: siteData.Site.SiteId,
226	                    webId: siteData.Site.WebId, taskListTitle: taskList.Title, taskListId: taskList.Id, taskListUrl: taskList.Url,
227	                    coverImage: taskList.Item_x005F_x0020_Cover || taskList.Item_x0020_Cover || taskList.coverImage
228	                }))
229	            );
230	            setSelectedSiteTitles(activeSites.map((s: any) => s.Site.Url));
231	            setActiveSitesSelectedItems(allTaskLists);
232	        } else {
233	            setSelectedSiteTitles([]);
234	            setActiveSitesSelectedItems([]);
235	        }
236	    };
237	
238	    const handleIndividualSitesChange = (siteUrl: any, checked: any, siteData: any) => {
239	        if (checked) {
240	            const taskLists = (siteData?.TaskLists || []).map((taskList: any) => ({
241	                siteTitle: siteData.Site.Title, siteUrl, siteId: siteData.Site.SiteId, webId: siteData.Site.WebId,
242	                taskListTitle: taskList.Title, taskListId: taskList.Id, taskListUrl: taskList.Url, coverImage: taskList.Item_x005F_x0020_Cover || taskList.Item_x0020_Cover || taskList.coverImage
243	            }));
244	            setActiveSitesSelectedItems(taskLists);
245	            setSelectedSiteTitles([siteUrl]);
246	        } else {
247	            const filtered = activeSitesSelectedItems.filter((m: any) => m.siteUrl !== siteUrl);
248	            setActiveSitesSelectedItems(filtered);
249	            setSelectedSiteTitles(selectedSiteTitles.filter((t: any) => t !== siteUrl));
250	        }
251	    };
252	
253	    useEffect(() => {
254	        console.log("[ResultTypeFilter] activeSites prop changed:", activeSites);
255	        if (activeSites && activeSites.length > 0 && activeSitesSelectedItems.length === 0 && useForOMTTool === true) {
256	            // Pre-check ONLY sites where IsVisible === true; all other sites remain listed but unchecked.
257	            const visibleSites = activeSites.filter((siteData: any) => siteData?.Site?.IsVisible === true);
258	            const defaultTaskLists = visibleSites.flatMap((siteData: any) =>
259	                siteData?.TaskLists?.map((taskList: any) => ({
260	                    siteTitle: siteData.Site.Title, siteUrl: siteData.Site.Url, siteId: siteData.Site.SiteId, webId: siteData.Site.WebId,
261	                    taskListTitle: taskList.Title, taskListId: taskList.Id, taskListUrl: taskList.Url, coverImage: taskList.Item_x005F_x0020_Cover || taskList.Item_x0020_Cover || taskList.coverImage
262	                })) || []
263	            );
264	            setActiveSitesSelectedItems(defaultTaskLists);
265	            setSelectedSiteTitles(visibleSites.map((siteData: any) => siteData.Site.Url));
266	        }
267	    }, [activeSites, useForOMTTool]);
268	
269	    const checkboxLabelCls = "flex items-center gap-2 cursor-pointer text-xs sm:text-sm text-slate-700 hover:text-slate-900 py-0.5 select-none transition-colors";
270	    const checkboxCls = "w-4 h-4 rounded border-slate-300 accent-[var(--SiteColor,#2F5596)] cursor-pointer shrink-0 transition-transform active:scale-90";
271	    const checkboxTextCls = "font-medium text-slate-700";
272	
273	    return (
274	        <div className="w-full space-y-3">
275	            {/* ── Sites Section ── */}
276	            <div className="mb-2">
277	                <details className="group" open>
278	                    <summary className="flex items-center justify-between cursor-pointer select-none py-3 px-4 rounded-lg bg-white border border-gray-200 text-slate-800 font-medium text-sm transition-all list-none shadow-sm mb-4">
279	                        <span className="flex items-center gap-3">
280	                            <ChevronRight className="w-5 h-5 text-[#2f5597] transition-transform group-open:rotate-90" />
281	                            <span className="text-[#2f5597] font-semibold text-base">Sites</span>
282	                        </span>
283	                        <div className="flex items-center gap-4">
284	                            {useForOMTTool === true && (
285	                                <span onClick={e => { e.stopPropagation(); e.nativeEvent.stopImmediatePropagation(); }} onMouseDown={e => { e.stopPropagation(); e.nativeEvent.stopImmediatePropagation(); }}>
286	                                    <Tooltip ComponentId={15962} />
287	                                </span>
288	                            )}
289	                        </div>
290	                    </summary>
291	
292	                    <label className={`${checkboxLabelCls} mt-2 px-2`}>
293	                        <input type="checkbox" ref={selectAllSitesRef} className={checkboxCls} checked={allSelectedSites} onChange={handleSelectAllSites} />
294	                        <span className={checkboxTextCls}>Select All</span>
295	                    </label>
296	
297	                    <div className="mb-3 mt-1.5 space-y-3 px-2">
298	                        {activeSites?.map((siteData: any, siteIndex: any) => (
299	                            <div key={siteIndex} className="mb-3">
300	                                {/* Site Title with Checkbox */}
301	                                <div className="flex items-center mb-2 pb-1 border-b border-slate-100">
302	                                    <input
303	                                        type="checkbox"
304	                                        id={`site-${siteIndex}`}
305	                                        className={`${checkboxCls} mr-2`}
306	                                        checked={selectedSiteTitles?.includes(siteData?.Site?.Url)}
307	                                        onChange={e => handleIndividualSitesChange(siteData?.Site?.Url, e.target.checked, siteData)}
308	                                    />
309	                                    <label className="text-xs font-semibold text-slate-800 cursor-pointer hover:text-blue-600 transition-colors" htmlFor={`site-${siteIndex}`}>
310	                                        {siteData.Site.Title}
311	                                    </label>
312	                                </div>
313	                                {/* Task Lists — Avatar circles */}
314	                                <div className="flex flex-wrap gap-2 ml-3">
315	                                    {siteData?.TaskLists?.map((taskList: any, taskIndex: any) => {
316	                                        const coverUrl = getCoverImageUrl(taskList);
317	                                        const isSelected = isTaskListSelected(taskList.Id);
318	                                        return (
319	                                            <div
320	                                                key={taskIndex}
321	                                                onClick={() => handleTaskListSelect(siteData, taskList)}
322	                                                className="relative cursor-pointer"
323	                                                title={taskList.Title}
324	                                            >
325	                                                <div
326	                                                    className={`w-[26px] h-[26px] rounded-full flex items-center justify-center relative transition-all ${isSelected ? 'ring-2 ring-blue-600 scale-105 shadow-md' : 'ring-1 ring-slate-200 shadow-sm hover:scale-105 hover:ring-blue-300'}`}
327	                                                    style={{ backgroundColor: coverUrl ? 'transparent' : getRandomColor(taskList.Id) }}
328	                                                >
329	                                                    {coverUrl ? (
330	                                                        <img src={coverUrl} alt={taskList.Title} className="w-[22px] h-[22px] rounded-full object-cover" />
331	                                                    ) : (
332	                                                        <span className="text-white font-bold text-[9px]">{getInitials(taskList.Title)}</span>
333	                                                    )}
334	                                                </div>
335	                                                {isSelected && (
336	                                                    <div className="absolute -top-0.5 -right-0.5 w-3.5 h-3.5 bg-blue-600 rounded-full flex items-center justify-center border border-white shadow">
337	                                                        <i className="text-white text-[7px] not-italic font-bold">✓</i>
338	                                                    </div>
339	                                                )}
340	                                            </div>
341	                                        );
342	                                    })}
343	                                </div>
344	                            </div>
345	                        ))}
346	                    </div>
347	                </details>
348	            </div>
349	
350	            {/* ── Result Type Section ── */}
351	            {(useForOMTTool === undefined || useForOMTTool === null || useForOMTTool === false) && (
352	                <div className="mb-2">
353	                    <details className="group" open>
354	                        <summary className="flex items-center justify-between cursor-pointer select-none py-2 px-2.5 rounded-lg bg-slate-100/80 hover:bg-slate-200/60 text-slate-800 font-semibold text-xs uppercase tracking-wider transition-all list-none">
355	                            <span>Result type</span>
356	                        </summary>
357	
358	                        {/* Select All */}
359	                        <label className={`${checkboxLabelCls} mt-2 px-2`}>
360	                            <input
361	                                type="checkbox"
362	                                className={checkboxCls}
363	                                checked={standaloneSelectAll}
364	                                onChange={e => handleStandaloneSelectAll(e.target.checked)}
365	                            />
366	                            <span className={checkboxTextCls}>Select All</span>
367	                        </label>
368	
369	                        {/* Document types */}
370	                        {(ContextValue?.useForOnlyTasks === undefined || ContextValue?.useForOnlyTasks != true) && (
371	                            <div className="mt-1 px-2">
372	                                {allFileTypeRefiners?.length > 0 && Object.keys(documentTypes)?.length > 0 && (
373	                                    <div className="mb-2">
374	                                        <label className={`${checkboxLabelCls} font-semibold text-slate-800`}>
375	                                            <input type="checkbox" className={checkboxCls} checked={documentSelectAll} onChange={e => handleDocumentSelectAll(e.target.checked)} />
376	                                            <span className={checkboxTextCls}>DOCUMENT</span>
377	                                        </label>
378	                                        <div className="flex flex-col gap-1 border-l-2 border-slate-200 pl-3 ml-3 my-1.5">
379	                                            {Object.keys(documentTypes)?.map(type => (
380	                                                <label key={type} className={checkboxLabelCls}>
381	                                                    <input type="checkbox" className={checkboxCls} checked={documentTypes[type]} onChange={e => handleDocumentTypeChange(type, e.target.checked)} />
382	                                                    <span className={checkboxTextCls}>{type.toUpperCase()}</span>
383	                                                </label>
384	                                            ))}
385	                                        </div>
386	                                    </div>
387	                                )}
388	                                {allFileTypeRefiners?.length === 0 && (
389	                                    <div className="mb-2">
390	                                        <label className={`${checkboxLabelCls} font-semibold text-slate-800`}>
391	                                            <input type="checkbox" className={checkboxCls} checked={resultTypeAllDoc} onChange={e => setResultTypesAllDoc(e.target.checked)} />
392	                                            <span className={checkboxTextCls}>DOCUMENT</span>
393	                                        </label>
394	                                    </div>
395	                                )}
396	                            </div>
397	                        )}
398	
399	                        {/* Task / Portfolio / Project */}
400	                        <div className="flex flex-col gap-1 px-2 mt-1">
401	                            <label className={checkboxLabelCls}>
402	                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Task} onChange={e => handleStandaloneTypeChange('Task', e.target.checked)} />
403	                                <span className={checkboxTextCls}>TASK (AWT)</span>
404	                            </label>
405	                            <label className={checkboxLabelCls}>
406	                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Portfolio} onChange={e => handleStandaloneTypeChange('Portfolio', e.target.checked)} />
407	                                <span className={checkboxTextCls}>PORTFOLIO (CSF)</span>
408	                            </label>
409	                            <label className={checkboxLabelCls}>
410	                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Project} onChange={e => handleStandaloneTypeChange('Project', e.target.checked)} />
411	                                <span className={checkboxTextCls}>PROJECT</span>
412	                            </label>
413	                        </div>
414	                    </details>
415	                </div>
416	            )}
417	        </div>
418	    );
419	};
420	
421	export default ResultTypeFilter;

